function LastDamage(npc)
	local kind = GetNpcParam(npc, 1)
	local sp = GetNpcParam(npc, 2)
	if PlayerIndex and PlayerIndex > 0 then PT45_OnKill(sp) end
	if kind == PT45_K_SUMMON then
		SetNpcParam(npc, 1, 0)
		SetNpcTimeout(npc, 18)
	end
end

function Timeout(npc)
